INSERT INTO indicators (id, group_id, unit, input, min_value, max_value, step, range_text, normal_low, normal_high, bands, sort) VALUES ('bp', 'heart', 'mmHg', 'bp', 50, 220, 1, '90–129 / 60–79', 90, 129, '[{"alertLow":90,"watchLow":90,"watchHigh":129,"alertHigh":139},{"alertLow":60,"watchLow":60,"watchHigh":79,"alertHigh":89}]'::jsonb, 0);
INSERT INTO indicator_i18n (indicator_id, lang, label, unit, how, device, why, space, source, steps, actions, risks) VALUES
  ('bp', 'en', 'Blood pressure', NULL, 'Seated, arm at heart level, after 5 min rest.', 'Automatic arm cuff', 'Spots strain on the heart and vessels before it causes symptoms.', 'Fluids shift toward the head in weightlessness, and the heart and vessels adapt to it.', 'AHA/ACC 2017 blood pressure guideline', '["Sit still for 5 minutes","Strap the cuff on the bare upper arm","Rest the arm at heart level","Press start and stay silent"]'::jsonb, '{"normal":["30 min on the cycle ergometer","Keep sodium low"],"watch-high":["Recheck in 15 min","Reduce sodium today","Keep daily aerobic exercise"],"alert-high":["Recheck now, both arms","Stop strenuous activity","Tell a crewmate"],"alert-low":["Lie down, legs raised","Drink 500 mL of fluids","Tell a crewmate"]}'::jsonb, '{"watch-high":"Elevated blood pressure","alert-high":"Hypertension risk","alert-low":"Low blood pressure"}'::jsonb),
  ('bp', 'es', 'Presión arterial', NULL, 'Sentado, brazo a la altura del corazón, tras 5 min de reposo.', 'Tensiómetro automático de brazo', 'Detecta sobrecarga del corazón y los vasos antes de que dé síntomas.', 'En ingravidez los fluidos suben hacia la cabeza, y el corazón y los vasos se adaptan.', 'Guía de presión arterial AHA/ACC 2017', '["Siéntate quieto 5 minutos","Coloca el brazalete en el brazo descubierto","Apoya el brazo a la altura del corazón","Pulsa inicio y no hables"]'::jsonb, '{"normal":["30 min en el cicloergómetro","Mantén bajo el sodio"],"watch-high":["Vuelve a medir en 15 min","Reduce el sodio hoy","Mantén el ejercicio aeróbico diario"],"alert-high":["Vuelve a medir ahora, en ambos brazos","Detén la actividad intensa","Avisa a un compañero"],"alert-low":["Acuéstate con las piernas elevadas","Bebe 500 mL de líquido","Avisa a un compañero"]}'::jsonb, '{"watch-high":"Presión arterial elevada","alert-high":"Riesgo de hipertensión","alert-low":"Presión arterial baja"}'::jsonb);
INSERT INTO indicators (id, group_id, unit, input, min_value, max_value, step, range_text, normal_low, normal_high, bands, sort) VALUES ('hr', 'heart', 'bpm', 'number', 30, 200, 1, '60–100', 60, 100, '[{"alertLow":50,"watchLow":60,"watchHigh":100,"alertHigh":110}]'::jsonb, 1);
INSERT INTO indicator_i18n (indicator_id, lang, label, unit, how, device, why, space, source, steps, actions, risks) VALUES
  ('hr', 'en', 'Resting heart rate', NULL, 'At rest, before coffee or exercise. Count 60 s.', 'Cuff or chest-strap monitor', 'A rising resting rate can signal fatigue, dehydration, or illness.', 'Without gravity the heart works less and can lose fitness over months.', 'American Heart Association, adult resting heart rate', '["Measure before getting up","Find the pulse at the wrist","Count beats for 60 seconds"]'::jsonb, '{"normal":["Keep aerobic sessions 5 days a week"],"watch-high":["Rest 10 min and recheck","Hydrate"],"watch-low":["Recheck after standing for 2 min"],"alert-high":["Stop activity and sit down","Record an ECG","Tell a crewmate"],"alert-low":["Record an ECG","Tell a crewmate"]}'::jsonb, '{"watch-high":"Raised resting heart rate","alert-high":"Tachycardia","watch-low":"Low heart rate","alert-low":"Bradycardia"}'::jsonb),
  ('hr', 'es', 'Frecuencia cardíaca en reposo', NULL, 'En reposo, antes del café o el ejercicio. Cuenta 60 s.', 'Tensiómetro o banda pectoral', 'Una frecuencia en reposo que sube puede indicar fatiga, deshidratación o enfermedad.', 'Sin gravedad el corazón trabaja menos y puede perder forma física en unos meses.', 'American Heart Association, frecuencia en reposo en adultos', '["Mide antes de levantarte","Busca el pulso en la muñeca","Cuenta los latidos durante 60 segundos"]'::jsonb, '{"normal":["Mantén sesiones aeróbicas 5 días por semana"],"watch-high":["Descansa 10 min y vuelve a medir","Hidrátate"],"watch-low":["Vuelve a medir tras 2 min de pie"],"alert-high":["Detén la actividad y siéntate","Registra un ECG","Avisa a un compañero"],"alert-low":["Registra un ECG","Avisa a un compañero"]}'::jsonb, '{"watch-high":"Frecuencia en reposo elevada","alert-high":"Taquicardia","watch-low":"Frecuencia cardíaca baja","alert-low":"Bradicardia"}'::jsonb);
INSERT INTO indicators (id, group_id, unit, input, min_value, max_value, step, range_text, normal_low, normal_high, bands, sort) VALUES ('glucose', 'metabolism', 'mg/dL', 'number', 20, 400, 1, '70–99', 70, 99, '[{"alertLow":54,"watchLow":70,"watchHigh":99,"alertHigh":125}]'::jsonb, 2);
INSERT INTO indicator_i18n (indicator_id, lang, label, unit, how, device, why, space, source, steps, actions, risks) VALUES
  ('glucose', 'en', 'Blood sugar', NULL, 'Fasting, finger-prick meter.', 'Finger-prick glucose meter', 'Shows how well the body turns food into energy.', 'Less movement and a fixed menu can make the body handle sugar worse.', 'American Diabetes Association, fasting glucose; compared with NASA OSDR OSD-575 (Inspiration4)', '["Measure before breakfast","Clean the fingertip and let it dry","Prick the side of the finger","Touch the drop to the strip"]'::jsonb, '{"normal":["Spread meals across the day","Walk or cycle after meals"],"watch-high":["Review meal timing","Add a cycle session after meals"],"alert-high":["Recheck in 1 h","Tell a crewmate"],"watch-low":["Eat a snack now","Recheck in 15 min"],"alert-low":["Take 15 g of fast sugar now","Recheck in 15 min","Tell a crewmate"]}'::jsonb, '{"watch-high":"Prediabetes range","alert-high":"Hyperglycemia","watch-low":"Low blood sugar","alert-low":"Hypoglycemia"}'::jsonb),
  ('glucose', 'es', 'Glucosa en sangre', NULL, 'En ayunas, con glucómetro de punción.', 'Glucómetro de punción digital', 'Muestra qué tan bien convierte el cuerpo los alimentos en energía.', 'Menos movimiento y un menú fijo pueden empeorar el manejo del azúcar.', 'American Diabetes Association, glucosa en ayunas; comparada con NASA OSDR OSD-575 (Inspiration4)', '["Mide antes del desayuno","Limpia la yema del dedo y deja secar","Pincha el costado del dedo","Toca la tira con la gota"]'::jsonb, '{"normal":["Reparte las comidas durante el día","Camina o pedalea tras las comidas"],"watch-high":["Revisa el horario de comidas","Añade una sesión de bicicleta tras comer"],"alert-high":["Vuelve a medir en 1 h","Avisa a un compañero"],"watch-low":["Come un refrigerio ahora","Vuelve a medir en 15 min"],"alert-low":["Toma 15 g de azúcar rápido ahora","Vuelve a medir en 15 min","Avisa a un compañero"]}'::jsonb, '{"watch-high":"Rango de prediabetes","alert-high":"Hiperglucemia","watch-low":"Glucosa baja","alert-low":"Hipoglucemia"}'::jsonb);
INSERT INTO indicators (id, group_id, unit, input, min_value, max_value, step, range_text, normal_low, normal_high, bands, sort) VALUES ('water', 'kidneys', 'L', 'number', 0, 8, 0.1, '2.0–4.0', 2, 4, '[{"alertLow":1.5,"watchLow":2,"watchHigh":4,"alertHigh":6}]'::jsonb, 3);
INSERT INTO indicator_i18n (indicator_id, lang, label, unit, how, device, why, space, source, steps, actions, risks) VALUES
  ('water', 'en', 'Fluid intake', NULL, 'Total drinks logged since waking.', 'Drink bag counter', 'Low fluid intake concentrates urine and favors kidney stones.', 'Bones release calcium in weightlessness, and thirst is weaker, so stones form more easily.', 'NASA Human Research Program, Risk of Renal Stone Formation', '["Count each drink bag","Add soups and rehydrated meals","Log the total in liters"]'::jsonb, '{"normal":["Keep a drink bag in reach"],"watch-low":["Drink 500 mL in the next hour","Set a drink reminder"],"alert-low":["Drink 1 L over 2 hours","Watch for flank pain","Tell a crewmate"],"watch-high":["Spread drinks across the day"]}'::jsonb, '{"watch-low":"Low fluid intake","alert-low":"Dehydration · kidney stone risk","watch-high":"High fluid intake"}'::jsonb),
  ('water', 'es', 'Ingesta de líquidos', NULL, 'Total de bebidas registradas desde que despertaste.', 'Contador de bolsas de bebida', 'Beber poco concentra la orina y favorece los cálculos renales.', 'En ingravidez los huesos liberan calcio y la sed es menor, así que los cálculos se forman con más facilidad.', 'Programa de Investigación Humana de la NASA, riesgo de cálculos renales', '["Cuenta cada bolsa de bebida","Suma sopas y comidas rehidratadas","Registra el total en litros"]'::jsonb, '{"normal":["Ten una bolsa de bebida a mano"],"watch-low":["Bebe 500 mL en la próxima hora","Programa un recordatorio para beber"],"alert-low":["Bebe 1 L en 2 horas","Atento a dolor en el costado","Avisa a un compañero"],"watch-high":["Reparte las bebidas durante el día"]}'::jsonb, '{"watch-low":"Ingesta baja de líquidos","alert-low":"Deshidratación · riesgo de cálculos renales","watch-high":"Ingesta alta de líquidos"}'::jsonb);
INSERT INTO indicators (id, group_id, unit, input, min_value, max_value, step, range_text, normal_low, normal_high, bands, sort) VALUES ('calcium', 'kidneys', 'mg/dL', 'scan', 5, 15, 0.1, '8.6–10.3', 8.6, 10.3, '[{"alertLow":8,"watchLow":8.6,"watchHigh":10.3,"alertHigh":11}]'::jsonb, 4);
INSERT INTO indicator_i18n (indicator_id, lang, label, unit, how, device, why, space, source, steps, actions, risks) VALUES
  ('calcium', 'en', 'Blood calcium', NULL, 'Weekly blood check.', 'Handheld blood analyzer', 'Calcium released from bone raises the risk of kidney stones.', 'Without load, bones release calcium into the blood and urine.', 'Lab reference range in NASA OSDR OSD-575 (Inspiration4 metabolic panel)', '["Clean the fingertip and let it dry","Fill the analyzer cartridge with one drop","Results sync automatically"]'::jsonb, '{"normal":["Keep fluids above 2 L a day"],"watch-high":["Drink 500 mL more today","Limit salt and animal protein"],"alert-high":["Recheck with the analyzer","Watch for flank pain","Tell a crewmate"],"watch-low":["Calcium and vitamin D with meals"],"alert-low":["Recheck with the analyzer","Tell a crewmate"]}'::jsonb, '{"watch-high":"High blood calcium · kidney stone risk","alert-high":"Hypercalcemia","watch-low":"Low blood calcium","alert-low":"Hypocalcemia"}'::jsonb),
  ('calcium', 'es', 'Calcio en sangre', NULL, 'Control semanal de sangre.', 'Analizador de sangre portátil', 'El calcio que liberan los huesos aumenta el riesgo de cálculos renales.', 'Sin carga, los huesos liberan calcio a la sangre y a la orina.', 'Rango de laboratorio de NASA OSDR OSD-575 (panel metabólico de Inspiration4)', '["Limpia la yema del dedo y deja secar","Llena el cartucho del analizador con una gota","Los resultados se sincronizan solos"]'::jsonb, '{"normal":["Mantén más de 2 L de líquidos al día"],"watch-high":["Bebe 500 mL más hoy","Limita la sal y la proteína animal"],"alert-high":["Vuelve a medir con el analizador","Atento a dolor en el costado","Avisa a un compañero"],"watch-low":["Calcio y vitamina D con las comidas"],"alert-low":["Vuelve a medir con el analizador","Avisa a un compañero"]}'::jsonb, '{"watch-high":"Calcio alto · riesgo de cálculos renales","alert-high":"Hipercalcemia","watch-low":"Calcio bajo","alert-low":"Hipocalcemia"}'::jsonb);
INSERT INTO indicators (id, group_id, unit, input, min_value, max_value, step, range_text, normal_low, normal_high, bands, sort) VALUES ('creatinine', 'kidneys', 'mg/dL', 'scan', 0.1, 5, 0.01, '0.6–1.35', 0.6, 1.35, '[{"alertLow":0.3,"watchLow":0.6,"watchHigh":1.35,"alertHigh":1.8}]'::jsonb, 5);
INSERT INTO indicator_i18n (indicator_id, lang, label, unit, how, device, why, space, source, steps, actions, risks) VALUES
  ('creatinine', 'en', 'Creatinine', NULL, 'Weekly blood check.', 'Handheld blood analyzer', 'Shows how well the kidneys filter the blood.', 'Dehydration and fluid shifts change how the kidneys filter.', 'Lab reference range in NASA OSDR OSD-575 (Inspiration4 metabolic panel)', '["Clean the fingertip and let it dry","Fill the analyzer cartridge with one drop","Results sync automatically"]'::jsonb, '{"normal":["Keep fluids above 2 L a day"],"watch-high":["Drink 500 mL more today","Recheck next week"],"alert-high":["Recheck with the analyzer","Tell a crewmate"],"watch-low":["Check your muscle mass trend"]}'::jsonb, '{"watch-high":"Reduced kidney filtering","alert-high":"Kidney function alert","watch-low":"Low creatinine"}'::jsonb),
  ('creatinine', 'es', 'Creatinina', NULL, 'Control semanal de sangre.', 'Analizador de sangre portátil', 'Muestra qué tan bien filtran la sangre los riñones.', 'La deshidratación y el desplazamiento de fluidos cambian cómo filtran los riñones.', 'Rango de laboratorio de NASA OSDR OSD-575 (panel metabólico de Inspiration4)', '["Limpia la yema del dedo y deja secar","Llena el cartucho del analizador con una gota","Los resultados se sincronizan solos"]'::jsonb, '{"normal":["Mantén más de 2 L de líquidos al día"],"watch-high":["Bebe 500 mL más hoy","Vuelve a medir la próxima semana"],"alert-high":["Vuelve a medir con el analizador","Avisa a un compañero"],"watch-low":["Revisa la tendencia de tu masa muscular"]}'::jsonb, '{"watch-high":"Filtrado renal reducido","alert-high":"Alerta de función renal","watch-low":"Creatinina baja"}'::jsonb);
INSERT INTO indicators (id, group_id, unit, input, min_value, max_value, step, range_text, normal_low, normal_high, bands, sort) VALUES ('temp', 'immune', '°C', 'number', 33, 42, 0.1, '36.1–37.4', 36.1, 37.4, '[{"alertLow":35.5,"watchLow":36.1,"watchHigh":37.4,"alertHigh":37.9}]'::jsonb, 6);
INSERT INTO indicator_i18n (indicator_id, lang, label, unit, how, device, why, space, source, steps, actions, risks) VALUES
  ('temp', 'en', 'Body temperature', NULL, 'Oral thermometer, 15 min after eating or drinking.', 'Digital oral thermometer', 'Fever is the first sign of an infection.', 'Stress and radiation weaken immunity, and microbes spread easily in a closed cabin.', 'Clinical reference range for oral temperature', '["Wait 15 min after eating or drinking","Place the tip under the tongue","Close the mouth until it beeps"]'::jsonb, '{"normal":["Wash hands before meals","Sleep 7 h or more"],"watch-high":["Hydrate and rest","Recheck in 2 h"],"alert-high":["Limit contact with the crew","Recheck in 1 h","Tell a crewmate"],"watch-low":["Add a layer and have a warm drink","Recheck in 1 h"],"alert-low":["Warm up now","Tell a crewmate"]}'::jsonb, '{"watch-high":"Mild fever","alert-high":"Fever · possible infection","watch-low":"Low body temperature","alert-low":"Hypothermia risk"}'::jsonb),
  ('temp', 'es', 'Temperatura corporal', NULL, 'Termómetro oral, 15 min después de comer o beber.', 'Termómetro oral digital', 'La fiebre es la primera señal de una infección.', 'El estrés y la radiación debilitan la inmunidad, y los microbios se propagan fácilmente en una cabina cerrada.', 'Rango clínico de temperatura oral', '["Espera 15 min tras comer o beber","Coloca la punta bajo la lengua","Cierra la boca hasta que suene"]'::jsonb, '{"normal":["Lávate las manos antes de comer","Duerme 7 h o más"],"watch-high":["Hidrátate y descansa","Vuelve a medir en 2 h"],"alert-high":["Limita el contacto con la tripulación","Vuelve a medir en 1 h","Avisa a un compañero"],"watch-low":["Abrígate y toma algo caliente","Vuelve a medir en 1 h"],"alert-low":["Entra en calor ahora","Avisa a un compañero"]}'::jsonb, '{"watch-high":"Febrícula","alert-high":"Fiebre · posible infección","watch-low":"Temperatura baja","alert-low":"Riesgo de hipotermia"}'::jsonb);
INSERT INTO indicators (id, group_id, unit, input, min_value, max_value, step, range_text, normal_low, normal_high, bands, sort) VALUES ('radiation', 'immune', 'mSv', 'scan', 0, 1000, 0.1, '< 180', 0, 180, '[{"alertLow":-1,"watchLow":-1,"watchHigh":180,"alertHigh":360}]'::jsonb, 7);
INSERT INTO indicator_i18n (indicator_id, lang, label, unit, how, device, why, space, source, steps, actions, risks) VALUES
  ('radiation', 'en', 'Radiation dose', NULL, 'Total since launch, read from your dosimeter.', 'Personal dosimeter', 'Total dose sets long-term cancer risk and limits mission time.', 'Beyond Earth''s shield, cosmic rays and solar storms add dose every day.', 'NASA-STD-3001 Vol. 1: career limit 600 mSv (watch at 30 %, alert at 60 %)', '["Wear the dosimeter at all times","Dock it daily to sync","Shelter if a solar storm alert sounds"]'::jsonb, '{"normal":["Sleep in the shielded crew quarters"],"watch-high":["Limit time in low-shield modules","Review dose plan with the crew"],"alert-high":["Move to the storm shelter","Tell a crewmate"]}'::jsonb, '{"watch-high":"High cumulative dose","alert-high":"Dose limit risk"}'::jsonb),
  ('radiation', 'es', 'Dosis de radiación', NULL, 'Total desde el lanzamiento, leído de tu dosímetro.', 'Dosímetro personal', 'La dosis total define el riesgo de cáncer a largo plazo y limita el tiempo de misión.', 'Fuera del escudo de la Tierra, los rayos cósmicos y las tormentas solares suman dosis cada día.', 'NASA-STD-3001 Vol. 1: límite de carrera 600 mSv (vigilar al 30 %, alerta al 60 %)', '["Lleva el dosímetro siempre","Conéctalo a diario para sincronizar","Refúgiate si suena la alerta de tormenta solar"]'::jsonb, '{"normal":["Duerme en los camarotes blindados"],"watch-high":["Limita el tiempo en módulos poco blindados","Revisa el plan de dosis con la tripulación"],"alert-high":["Ve al refugio contra tormentas","Avisa a un compañero"]}'::jsonb, '{"watch-high":"Dosis acumulada alta","alert-high":"Riesgo de superar el límite de dosis"}'::jsonb);
INSERT INTO indicators (id, group_id, unit, input, min_value, max_value, step, range_text, normal_low, normal_high, bands, sort) VALUES ('solar', 'immune', 'events', 'scan', 0, 20, 1, '0', 0, 0, '[{"alertLow":-1,"watchLow":-1,"watchHigh":0,"alertHigh":0}]'::jsonb, 8);
INSERT INTO indicator_i18n (indicator_id, lang, label, unit, how, device, why, space, source, steps, actions, risks) VALUES
  ('solar', 'en', 'Solar particle events', NULL, 'Live feed, last 3 days.', 'NASA DONKI space weather feed', 'A solar storm can deliver a large radiation dose in hours.', 'Outside Earth''s magnetic field, solar particle events are the biggest short-term radiation threat.', 'Live data from NASA DONKI (CCMC). NASA-STD-3001: 250 mSv limit per solar event', '["Watch for the solar storm alert","Move to the shielded storm shelter","Stay until the all-clear"]'::jsonb, '{"normal":["Know your route to the storm shelter"],"alert-high":["Move to the storm shelter now","Stay until the all-clear","Tell a crewmate"]}'::jsonb, '{"alert-high":"Solar particle event · shelter now"}'::jsonb),
  ('solar', 'es', 'Eventos de partículas solares', 'eventos', 'Datos en vivo, últimos 3 días.', 'Datos de clima espacial NASA DONKI', 'Una tormenta solar puede dar una dosis alta de radiación en pocas horas.', 'Fuera del campo magnético de la Tierra, los eventos de partículas solares son la mayor amenaza de radiación a corto plazo.', 'Datos en vivo de NASA DONKI (CCMC). NASA-STD-3001: límite de 250 mSv por evento solar', '["Atento a la alerta de tormenta solar","Ve al refugio blindado contra tormentas","Quédate hasta que den el aviso de fin"]'::jsonb, '{"normal":["Conoce tu ruta al refugio contra tormentas"],"alert-high":["Ve al refugio contra tormentas ahora","Quédate hasta el aviso de fin","Avisa a un compañero"]}'::jsonb, '{"alert-high":"Evento de partículas solares · refúgiate ahora"}'::jsonb);
INSERT INTO indicators (id, group_id, unit, input, min_value, max_value, step, range_text, normal_low, normal_high, bands, sort) VALUES ('sleep', 'brain', 'h', 'number', 0, 16, 0.5, '7–9', 7, 9.5, '[{"alertLow":6,"watchLow":7,"watchHigh":9.5,"alertHigh":12}]'::jsonb, 9);
INSERT INTO indicator_i18n (indicator_id, lang, label, unit, how, device, why, space, source, steps, actions, risks) VALUES
  ('sleep', 'en', 'Sleep', NULL, 'Hours actually asleep last night.', 'Sleep log or wrist actigraph', 'Short sleep slows reactions and raises the risk of errors.', 'Sixteen sunrises a day, noise, and stress break the body clock.', 'National Sleep Foundation and AASM adult sleep duration', '["Note the time you fell asleep","Note the time you woke","Subtract time spent awake"]'::jsonb, '{"normal":["Keep the same sleep window","Dim lights 1 h before bed"],"watch-low":["Dim lights 1 h before bed","Keep a fixed sleep window","No screens in the sleep station"],"alert-low":["Request a schedule change","Tell a crewmate"],"watch-high":["Check for fatigue or illness"]}'::jsonb, '{"watch-low":"Sleep deficit","alert-low":"Severe sleep loss","watch-high":"Oversleeping"}'::jsonb),
  ('sleep', 'es', 'Sueño', NULL, 'Horas realmente dormidas anoche.', 'Registro de sueño o actígrafo de muñeca', 'Dormir poco enlentece los reflejos y aumenta el riesgo de errores.', 'Dieciséis amaneceres al día, ruido y estrés alteran el reloj biológico.', 'National Sleep Foundation y AASM, horas de sueño en adultos', '["Anota la hora en que te dormiste","Anota la hora en que despertaste","Resta el tiempo que pasaste despierto"]'::jsonb, '{"normal":["Mantén el mismo horario de sueño","Baja la luz 1 h antes de dormir"],"watch-low":["Baja la luz 1 h antes de dormir","Mantén un horario fijo de sueño","Sin pantallas en el camarote"],"alert-low":["Pide un cambio de horario","Avisa a un compañero"],"watch-high":["Revisa si hay fatiga o enfermedad"]}'::jsonb, '{"watch-low":"Déficit de sueño","alert-low":"Pérdida grave de sueño","watch-high":"Exceso de sueño"}'::jsonb);
INSERT INTO indicators (id, group_id, unit, input, min_value, max_value, step, range_text, normal_low, normal_high, bands, sort) VALUES ('mood', 'brain', '/ 5', 'scale', 1, 5, 1, '4–5', 4, 5, '[{"alertLow":3,"watchLow":4,"watchHigh":5,"alertHigh":5}]'::jsonb, 10);
INSERT INTO indicator_i18n (indicator_id, lang, label, unit, how, device, why, space, source, steps, actions, risks) VALUES
  ('mood', 'en', 'Mood', NULL, 'How do you feel today, overall?', 'Self-report', 'Low mood over days affects sleep, teamwork, and safety.', 'Isolation, confinement, and distance from home weigh on mood.', 'Self-report scale', '["Pause for a moment","Think about the whole day","Pick the face that fits"]'::jsonb, '{"normal":["Share a meal with the crew","Keep a weekly call home"],"watch-low":["Schedule a private call home","Make time for a hobby","Share a meal with the crew"],"alert-low":["Talk to the behavioral health team","Tell a crewmate how you feel"]}'::jsonb, '{"watch-low":"Low mood","alert-low":"Behavioral health risk"}'::jsonb),
  ('mood', 'es', 'Estado de ánimo', NULL, '¿Cómo te sientes hoy, en general?', 'Autoevaluación', 'Un ánimo bajo durante días afecta el sueño, el trabajo en equipo y la seguridad.', 'El aislamiento, el confinamiento y la distancia de casa pesan en el ánimo.', 'Escala de autoevaluación', '["Haz una pausa","Piensa en el día completo","Elige la cara que encaja"]'::jsonb, '{"normal":["Comparte una comida con la tripulación","Mantén una llamada semanal a casa"],"watch-low":["Agenda una llamada privada a casa","Dedica tiempo a un pasatiempo","Comparte una comida con la tripulación"],"alert-low":["Habla con el equipo de salud conductual","Cuéntale a un compañero cómo te sientes"]}'::jsonb, '{"watch-low":"Ánimo bajo","alert-low":"Riesgo de salud conductual"}'::jsonb);
INSERT INTO indicators (id, group_id, unit, input, min_value, max_value, step, range_text, normal_low, normal_high, bands, sort) VALUES ('bone', 'bones', '%', 'scan', -20, 5, 0.1, '> −3 %', -3, 1, '[{"alertLow":-6,"watchLow":-3,"watchHigh":100,"alertHigh":100}]'::jsonb, 11);
INSERT INTO indicator_i18n (indicator_id, lang, label, unit, how, device, why, space, source, steps, actions, risks) VALUES
  ('bone', 'en', 'Bone density', NULL, 'Change vs. preflight baseline.', 'Weekly ultrasound scan', 'Weaker bones break more easily after landing.', 'Without load, hip and spine bones lose 1–1.5 % of mass each month.', 'NASA Human Research Program, Risk of Early Onset Osteoporosis', '["Scheduled weekly by the flight surgeon","Scan the heel and hip with the probe","Results sync automatically"]'::jsonb, '{"normal":["Daily resistance session","Calcium and vitamin D with meals"],"watch-low":["Add load to resistance sessions","Calcium and vitamin D with meals"],"alert-low":["Review the exercise plan","Tell a crewmate"]}'::jsonb, '{"watch-low":"Bone loss","alert-low":"Osteoporosis risk"}'::jsonb),
  ('bone', 'es', 'Densidad ósea', NULL, 'Cambio respecto a la línea base previa al vuelo.', 'Ecografía semanal', 'Los huesos débiles se rompen con más facilidad tras el aterrizaje.', 'Sin carga, los huesos de la cadera y la columna pierden 1–1,5 % de masa al mes.', 'Programa de Investigación Humana de la NASA, riesgo de osteoporosis temprana', '["La programa cada semana el médico de vuelo","Explora talón y cadera con la sonda","Los resultados se sincronizan solos"]'::jsonb, '{"normal":["Sesión diaria de resistencia","Calcio y vitamina D con las comidas"],"watch-low":["Aumenta la carga en las sesiones de resistencia","Calcio y vitamina D con las comidas"],"alert-low":["Revisa el plan de ejercicio","Avisa a un compañero"]}'::jsonb, '{"watch-low":"Pérdida ósea","alert-low":"Riesgo de osteoporosis"}'::jsonb);
INSERT INTO indicators (id, group_id, unit, input, min_value, max_value, step, range_text, normal_low, normal_high, bands, sort) VALUES ('muscle', 'muscles', '%', 'scan', -30, 5, 0.1, '> −5 %', -5, 1, '[{"alertLow":-10,"watchLow":-5,"watchHigh":100,"alertHigh":100}]'::jsonb, 12);
INSERT INTO indicator_i18n (indicator_id, lang, label, unit, how, device, why, space, source, steps, actions, risks) VALUES
  ('muscle', 'en', 'Muscle mass', NULL, 'Change vs. preflight baseline.', 'Weekly ultrasound scan', 'Strong muscles keep you safe during spacewalks and landing.', 'Legs and back shrink fast when they no longer hold the body up.', 'NASA Human Research Program, Risk of Reduced Muscle Mass and Strength', '["Scheduled weekly by the flight surgeon","Scan thigh and calf with the probe","Results sync automatically"]'::jsonb, '{"normal":["Resistance training 6 days a week","Protein with every meal"],"watch-low":["Add one resistance session","Protein with every meal"],"alert-low":["Review the exercise plan","Tell a crewmate"]}'::jsonb, '{"watch-low":"Muscle loss","alert-low":"Severe muscle atrophy"}'::jsonb),
  ('muscle', 'es', 'Masa muscular', NULL, 'Cambio respecto a la línea base previa al vuelo.', 'Ecografía semanal', 'Unos músculos fuertes te protegen en las caminatas espaciales y en el aterrizaje.', 'Piernas y espalda se reducen rápido cuando ya no sostienen el cuerpo.', 'Programa de Investigación Humana de la NASA, riesgo de pérdida de masa y fuerza muscular', '["La programa cada semana el médico de vuelo","Explora muslo y pantorrilla con la sonda","Los resultados se sincronizan solos"]'::jsonb, '{"normal":["Entrenamiento de resistencia 6 días por semana","Proteína en cada comida"],"watch-low":["Añade una sesión de resistencia","Proteína en cada comida"],"alert-low":["Revisa el plan de ejercicio","Avisa a un compañero"]}'::jsonb, '{"watch-low":"Pérdida muscular","alert-low":"Atrofia muscular grave"}'::jsonb);
